const e = $json;
const route = e.decision?.route ?? 'GENERAL';
const i = e.intelligence ?? {};
const r = e.response?.validated ?? {};
const resolution = e.context?.resolution ?? {};
const create = !!resolution.create_lead;
const update = !!resolution.update_lead;
const name = i.customer?.name ?? e.context?.customer?.name ?? e.context?.lead?.name ?? '';
const mail = i.customer?.email ?? e.context?.customer?.email ?? e.context?.lead?.email ?? '';
const phone = e.event?.sender ?? i.customer?.phone ?? '';
const parent = e.identity?.parent_message_id ?? e.event?.message_id ?? '';
const language = e.decision?.language ?? 'English';
const signal = i.appointment?.signal ?? 'NONE';
const historyText = (e.context?.sms_history ?? []).map(x => x.content ?? '').join(' ');
let fe;
if (signal === 'CANCEL') fe = 'Appointment Cancellation Requested';
else if (signal === 'BOOKED') fe = 'Appointment Booked';
else if (/member of our dealership team will connect|manager.*follow up/i.test(historyText)) fe = 'Managerial Review';
else fe = create === 'true' ? 'Lead' : 'Contacted';
const common = { lead_name: name, lead_mail: mail, lead_phone: phone, source: 'SMS', message_id: e.event?.message_id ?? '', create_lead: create, update_lead: update, sender_number: e.event?.sender ?? '', recipient_number: e.event?.recipient ?? '', user_language: language, appointment_cancellation_requested: signal === 'CANCEL' };
if (route === 'DND') {
  return [{ json: { lead_status: 'DND', ...common, response: null, request_query: String(e.event?.content ?? ''), parent_id: parent, fe_lead_status: 'DND', send_user_response: false, send_manager_sms: true, manager_sms: e.decision?.manager_sms ?? null, appointment_cancellation_requested: false } }];
}
if (route === 'ESCALATION') {
  const blocked = !!e.decision?.block_delivery;
  return [{ json: { lead_status: 'Managerial Review', ...common, response: null, request_query: String(e.event?.content ?? ''), parent_id: parent, fe_lead_status: 'Managerial Review', send_user_response: !blocked, user_response: blocked ? null : r.sms_response, send_manager_sms: !blocked, manager_sms: blocked ? null : (e.decision?.manager_sms ?? null), appointment_cancellation_requested: false } }];
}
if (route === 'EMAIL_HANDOFF') {
  return [{ json: { lead_status: 'First Response Sent', ...common, response: r.email_body, parent_id: parent, request: String(e.event?.content ?? '').trim(), fe_lead_status: 'Lead', response_mode: 'email', preferred_communication_mode_selected: true, preferred_communication_mode: 'email', preferred_communication_mode_old_messageID: parent, appointment_cancellation_requested: false } }];
}
if (route === 'BOOKING') {
  return [{ json: { lead_status: i.journey?.intent ?? 'Visit Booked', ...common, response: r.sms_response, request_query: String(e.event?.content ?? '').trim(), parent_message_id: parent, booking_status: true, booking_date: r.booking_date ?? '', booking_time: r.booking_time ?? '', fe_lead_status: 'Appointment Booked', appointment_cancellation_requested: false } }];
}
if (route === 'VISIT') {
  return [{ json: { lead_status: i.journey?.intent ?? 'Visit Requested', ...common, response: r.sms_response, request_query: String(e.event?.content ?? '').trim(), parent_message_id: parent, fe_lead_status: fe } }];
}
return [{ json: { lead_status: 'First Response Sent', ...common, response: r.sms_response, request_query: String(e.event?.content ?? '').trim(), parent_message_id: parent, fe_lead_status: fe } }];
